/**
 * Unit tests for org.apache.commons.lang.StringEscapeUtils.escapeJava
 */
public class StringEscapeUtils_escapeJava_TriageGen0Test {













    @Test
    public void testEscapeJava_UnicodeCharacters() {
        // Test non-printable or high-range unicode characters
        // \u0000 (Null character)
        assertEquals("\\u0000", StringEscapeUtils.escapeJava("\u0000"));

        // \u001F (Unit Separator)
        assertEquals("\\u001f", StringEscapeUtils.escapeJava("\u001f"));

        // \u1234 (General Unicode)
        assertEquals("\\u1234", StringEscapeUtils.escapeJava("\u1234"));
    }




}

