import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.StringEscapeUtils.escapeJava
 */
public class StringEscapeUtils_escapeJava_TriageGen0Test {

















    @Test
    public void testEscapeJava_RoundTrip() {
        // Verify that unescapeJava reverses escapeJava
        String original = "Line1\nLine2\t\"Tabbed\"\u0001";
        String escaped = StringEscapeUtils.escapeJava(original);
        assertEquals(original, StringEscapeUtils.unescapeJava(escaped));
    }
}
